// The bookings example's transpile output: developer-owned generated source
// and the tests that drive it. This example shows what runs at the same time
// and what takes turns (the wiki guide Concurrency): a slot booked once, keyed
// on the slot the request carries; a cancellation keyed on its booking; an
// hourly waitlist sweep whose firings are commits of their own; and a cap over
// the whole waitlist that deliberately makes joining commits take turns.
// Regenerated by `gradle generate`.
plugins {
    kotlin("jvm")
}

group = "velle"

repositories {
    mavenCentral()
}

dependencies {
    implementation(project(":compiler"))
    testImplementation(kotlin("test"))
    testImplementation(project(":stores:sqlite")) // the flows re-run over real storage
}

tasks.test {
    useJUnitPlatform()
}

tasks.register<JavaExec>("generate") {
    description = "Regenerate the Bookings typed surface, executable specs, and diagrams from bookings.velle"
    classpath = sourceSets["main"].runtimeClasspath
    mainClass.set("velle.GenerateKt")
    args("../bookings.velle", "Bookings", "--diagrams")
}

kotlin {
    compilerOptions {
        jvmTarget.set(org.jetbrains.kotlin.gradle.dsl.JvmTarget.JVM_21)
    }
}

java {
    sourceCompatibility = JavaVersion.VERSION_21
    targetCompatibility = JavaVersion.VERSION_21
}
